// The Notification Service Extension: the only place a sealed push is ever plaintext.
//
// A Custos instance HPKE-seals a notification to this device's key and hands it to a relay
// that holds the APNs key but no decryption key. The relay and Apple both carry the payload
// as opaque bytes beside a placeholder alert ("Custos / Encrypted notification"), and
// `mutable-content: 1` routes it here for the ~30 seconds iOS allows before it gives up and
// shows the placeholder.
//
// # The constraint that shapes everything below
//
// **An NSE cannot suppress an alert push.** If this code fails, times out, or declines to
// attach content, iOS displays the original payload anyway. So "drop what we cannot verify"
// is not on the menu; the only thing under this extension's control is *what the user reads*.
// The rule is therefore absolute: content that opened under HPKE Auth mode renders as
// content, and everything else renders as the explicit unverified notice. Never a guess,
// never a partial render, never the placeholder passed through as though it were news.
//
// That is what keeps a relay's junk push from being an impersonation. The relay can always
// generate noise — it holds the APNs key — but noise arrives labelled as unverifiable, which
// is detectable spam and grounds for switching relays, not a forged message from your server.

import UserNotifications

/// The decision the extension makes about one payload, split out from the `UNNotification`
/// machinery so every branch is reachable from a test.
enum NotifyOutcome: Equatable {
    case rendered(NotifyPayload)
    case unverified(NotifyFailureReason, kid: Int?)
}

enum NotifyResolver {
    /// The user-visible copy for a payload this device cannot vouch for.
    ///
    /// Deliberately says what happened and nothing more. It names no sender ("from your
    /// Custos instance" is a category, not a claim about which one), states no cause the
    /// extension cannot know, and offers no action — the actionable version of this lives in
    /// Settings, where the breadcrumbs can say whether it happened once or twenty times.
    static let unverifiedTitle = "Unverified notification"
    static let unverifiedBody = "Couldn't verify a notification from your Custos instance."

    /// Resolve an APNs `userInfo` into what should be shown.
    ///
    /// Pure over its inputs — the Keychain reads happen in the caller — so the whole failure
    /// ladder is exercisable on a simulator with no push and no registered key.
    static func resolve(
        userInfo: [AnyHashable: Any],
        recipientPrivateKey: Data?,
        pins: PinnedSenderKeys
    ) -> NotifyOutcome {
        guard let envelope = NotifyEnvelope.parse(userInfo: userInfo) else {
            return .unverified(.malformedPayload, kid: nil)
        }
        guard let recipientPrivateKey else {
            return .unverified(.keysUnavailable, kid: envelope.kid)
        }

        let candidates = pins.candidates(for: envelope.kid)
        guard !candidates.isEmpty else {
            return .unverified(.unknownKid, kid: envelope.kid)
        }

        // Try every key pinned under this `kid`. See `PinnedSenderKeys.candidates` for why
        // there can be more than one; Auth mode makes a wrong guess free.
        for didKey in candidates {
            guard let senderBytes = DidKey.p256PublicKeyBytes(from: didKey) else { continue }
            guard let plaintext = NotifyCrypto.open(
                recipientPrivateKey: recipientPrivateKey,
                senderPublicKey: senderBytes,
                encapsulatedKey: envelope.enc,
                ciphertext: envelope.ct
            ) else { continue }

            // Past this point the payload is authenticated: only a holder of a pinned sender
            // private key could have produced it. A body we cannot parse is therefore our own
            // bug or a version skew, not an attack — but it still cannot be rendered as
            // content, because there is no content to render.
            guard let payload = NotifyPayload.decode(plaintext) else {
                return .unverified(.malformedPlaintext, kid: envelope.kid)
            }
            return .rendered(payload)
        }

        return .unverified(.openFailed, kid: envelope.kid)
    }
}

final class NotificationService: UNNotificationServiceExtension {
    private var contentHandler: ((UNNotificationContent) -> Void)?
    private var bestAttempt: UNMutableNotificationContent?

    override func didReceive(
        _ request: UNNotificationRequest,
        withContentHandler contentHandler: @escaping (UNNotificationContent) -> Void
    ) {
        self.contentHandler = contentHandler
        guard let content = request.content.mutableCopy() as? UNMutableNotificationContent else {
            // `UNNotificationContent.mutableCopy()` is documented to return the mutable class, so
            // this is a platform-contract violation rather than a state a payload can produce.
            // It still cannot be allowed to deliver `request.content`: that content is immutable,
            // so the sealed block cannot be stripped from it, and its title/body are the relay's
            // placeholder — the one combination the extension's rule forbids. A fresh content
            // carrying only the notice is the sole way to honour both halves here.
            //
            // No breadcrumb: the failure vocabulary describes payloads, and reporting this as a
            // payload problem would send the user looking at their keys for a bug in ours.
            contentHandler(Self.unverifiedContent())
            return
        }
        bestAttempt = content

        let outcome = NotifyResolver.resolve(
            userInfo: request.content.userInfo,
            recipientPrivateKey: NotifyKeychain.read(
                account: NotifyKeychain.notificationKeyAccount
            ),
            pins: PinnedSenderKeys.parse(
                NotifyKeychain.read(account: NotifyKeychain.pinnedSenderKeysAccount)
            )
        )

        switch outcome {
        case let .rendered(payload):
            content.title = payload.title
            content.body = payload.body
            // Routing survives ONLY on the verified path: `ezpdsRoute`'s presence in a
            // delivered notification is the statement that HPKE Auth vouched for it, which
            // is what lets the app deep-link on a tap without re-deciding trust.
            if let route = NotifyRoute.userInfo(for: payload) {
                content.userInfo[NotifyRoute.userInfoKey] = route
            }
        case let .unverified(reason, kid):
            content.title = NotifyResolver.unverifiedTitle
            content.body = NotifyResolver.unverifiedBody
            NotifyBreadcrumbs.record(reason, kid: kid)
        }

        Self.finish(content)
        contentHandler(content)
    }

    /// iOS is about to give up on us.
    ///
    /// Whatever is in `bestAttempt` is delivered, so this path has to satisfy the same two
    /// obligations `didReceive` does — say "unverified" rather than let the relay's placeholder
    /// stand in for the server's words, and strip the sealed block. Neither gets an exception
    /// for running late: a timeout is the one route by which unstripped ciphertext, under a
    /// title the user reads as authentic, could reach the delivered-notification list.
    override func serviceExtensionTimeWillExpire() {
        guard let contentHandler, let bestAttempt else { return }
        // The presence of the sealed block IS the "we never finished" signal — `finish` strips it
        // and writes the notice in the same breath, so it can only still be here if resolution
        // was cut short. Testing that rather than the title keeps the two facts from drifting.
        if bestAttempt.userInfo[NotifyEnvelope.userInfoKey] != nil {
            bestAttempt.title = NotifyResolver.unverifiedTitle
            bestAttempt.body = NotifyResolver.unverifiedBody
        }
        Self.finish(bestAttempt)
        contentHandler(bestAttempt)
    }

    /// The last thing done to any content that leaves this extension.
    ///
    /// The sealed block has served its purpose and must not ride along into the delivered
    /// notification, where the app — and anything reading `UNUserNotificationCenter`'s delivered
    /// list — would see ciphertext it has no use for. Factored out because "every exit path"
    /// is the actual requirement, and inlining it at each one is how an exit path gets missed.
    private static func finish(_ content: UNMutableNotificationContent) {
        content.userInfo.removeValue(forKey: NotifyEnvelope.userInfoKey)
    }

    /// A fresh content carrying nothing but the unverified notice.
    ///
    /// For the exit where no mutable copy exists to strip, so substituting content is the only
    /// way to avoid delivering the sealed block.
    private static func unverifiedContent() -> UNMutableNotificationContent {
        let content = UNMutableNotificationContent()
        content.title = NotifyResolver.unverifiedTitle
        content.body = NotifyResolver.unverifiedBody
        return content
    }
}

// The diagnostic trail behind the unverified notice.
//
// iOS will not let a Notification Service Extension suppress an alert push, so a payload the
// device cannot verify still produces a banner. The banner says so honestly — but on its own
// it is a mystery: a user seeing "couldn't verify" three days running has no way to tell a
// key desync from a relay sending junk. These breadcrumbs are what turns that into something
// Settings can state, and they are the *only* thing the extension leaves behind.
//
// They are written to the shared Keychain rather than an app-group container. The group the
// extension already needs (`org.obsign.shared`) requires no Apple Developer portal work,
// where an app group would be a second entitlement on both bundles; and the protection class
// is the same one the notification key already carries, so a breadcrumb is writable in
// exactly the moments a decryption is attemptable. The one case that buys: a push arriving
// before the first unlock after a reboot leaves no breadcrumb — but that state repairs itself
// the moment the user unlocks, and is the least diagnostic-worthy of the failures.

import Foundation

/// Why a payload could not be rendered as authentic. Shared vocabulary with
/// `notifications::NotificationFailureReason` on the Rust side — the app maps these onto the
/// sentences Settings shows, so a new case here needs one there.
enum NotifyFailureReason: String {
    /// No `ezpds` block, or one this version cannot parse. What a junk push from a
    /// misbehaving relay looks like — the relay holds the APNs key and can always send noise.
    case malformedPayload = "MALFORMED_PAYLOAD"
    /// The notification key or the pin document could not be read: either nothing is
    /// registered yet, or the Keychain is locked before the first unlock after a reboot.
    case keysUnavailable = "KEYS_UNAVAILABLE"
    /// No pinned sender key carries the envelope's `kid`. The key-desync signature: the
    /// instance rotated and this device has not re-pinned since.
    case unknownKid = "UNKNOWN_KID"
    /// Candidates existed and every one of them failed to open the payload. HPKE Auth mode
    /// failing closed — a forged or corrupted ciphertext, or a genuinely stale pin.
    case openFailed = "OPEN_FAILED"
    /// The payload opened — so it *was* authentic — but carried nothing renderable.
    case malformedPlaintext = "MALFORMED_PLAINTEXT"
}

/// One recorded failure.
struct NotifyFailure: Codable, Equatable {
    let at: String
    let reason: String
    /// The envelope's `kid`, where there was a parseable envelope to read one from.
    let kid: Int?
}

/// The stored log: newest first, bounded.
struct NotifyFailureLog: Codable {
    static let supportedVersion = 1
    /// Enough to show a pattern ("five in the last day"), small enough that the whole log
    /// stays a single modest Keychain item. Older entries answer no question the newer ones
    /// do not.
    static let capacity = 20

    var version: Int
    var failures: [NotifyFailure]

    static let empty = NotifyFailureLog(version: supportedVersion, failures: [])

    /// Read the log, treating anything unreadable as empty.
    ///
    /// Fail-open like the pin store: this is a diagnostic trail, and refusing to append to a
    /// damaged one would lose the very breadcrumb that is being recorded right now.
    static func parse(_ raw: Data?) -> NotifyFailureLog {
        guard let raw,
              let decoded = try? JSONDecoder().decode(NotifyFailureLog.self, from: raw),
              decoded.version == supportedVersion
        else { return .empty }
        return decoded
    }

    /// Prepend `failure`, dropping the oldest beyond [`capacity`]. Pure, so the trimming rule
    /// is testable without a Keychain.
    func appending(_ failure: NotifyFailure) -> NotifyFailureLog {
        NotifyFailureLog(
            version: Self.supportedVersion,
            failures: Array(([failure] + failures).prefix(Self.capacity))
        )
    }
}

enum NotifyBreadcrumbs {
    /// Record one failure, best effort.
    ///
    /// Every outcome is swallowed. The extension has one job left at this point — putting an
    /// honest notice on screen before iOS's timeout — and a Keychain that will not take a
    /// diagnostic must not be allowed to cost the user that. A lost breadcrumb is a lost
    /// breadcrumb; a lost `contentHandler` call is the placeholder text shown instead.
    static func record(_ reason: NotifyFailureReason, kid: Int?, now: Date = Date()) {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime]
        let failure = NotifyFailure(
            at: formatter.string(from: now),
            reason: reason.rawValue,
            kid: kid
        )

        let log = NotifyFailureLog
            .parse(NotifyKeychain.read(account: NotifyKeychain.failureLogAccount))
            .appending(failure)

        guard let encoded = try? JSONEncoder().encode(log) else { return }
        NotifyKeychain.write(account: NotifyKeychain.failureLogAccount, data: encoded)
    }
}

import { invoke } from '@tauri-apps/api/core';
import type { UnlockReason } from './identity';

// ── Push notifications (the device half of the encrypted notification relay) ──
//
// The wallet registers a per-device P-256 key with each identity's Custos, which seals every
// push payload to it; a Notification Service Extension decrypts on arrival. Nothing here
// decrypts — these wrappers cover the two calls that keep the arrangement working: registering
// the device, and re-pinning the instance's sender keys.
//
// Re-pinning is the load-bearing one. A sender key the operator revokes stops being trusted on
// this device at its next contact with that Custos and not before, so `refreshNotificationSenderKeys`
// belongs on every successful contact — it is a security property with a cadence, not a cache
// refresh.
//
// Neither call is biometric-gated: no identity material is signed or exposed, and a prompt on
// the onboarding completion path would be a demand the user cannot connect to anything they did.

/** What a registration attempt actually did. */
export type RegistrationStatus =
  /** The server stored the registration and is minting a relay handle for it. */
  | 'REGISTERED'
  /**
   * No APNs token yet — the simulator never issues one, the user may not have granted
   * permission, and on a granted device it arrives asynchronously after launch. An ordinary
   * state, not a failure: the token-change callback re-registers when one shows up.
   */
  | 'AWAITING_APNS_TOKEN'
  /**
   * The identity's host serves no notification routes. Always true for a claimed identity on a
   * standard PDS, and for a Custos whose operator configured no relay.
   */
  | 'UNSUPPORTED';

export type RegistrationOutcome = {
  status: RegistrationStatus;
  /** The stable identifier this device registered under (the server keys rows on it). */
  deviceUuid: string;
  /** The device's notification `did:key`, or null when the attempt stopped before one was needed. */
  notificationKeyId: string | null;
};

/** One sender key this device trusts for a given host. */
export type SenderKey = {
  /** Instance-scoped key id — a sealed payload's envelope names which key sealed it. */
  kid: number;
  /** The P-256 `did:key` to verify the seal against. */
  publicKey: string;
};

/** The outcome of a re-pin. */
export type SenderKeyPinning = {
  /** The hosting server whose set was fetched (normalized). */
  host: string;
  /**
   * True when the server answered and the stored set was replaced wholesale — which is how a
   * revoked key stops being trusted. False when the host serves no notification routes, in which
   * case the stored set was left exactly as it was.
   */
  pinned: boolean;
  /** The set now pinned for this host. */
  keys: SenderKey[];
};

/**
 * Why the Notification Service Extension could not vouch for a payload.
 *
 * Kept open-ended (`(string & {})`) rather than a closed union: the extension is a separate
 * bundle that versions on its own schedule, so an unrecognized reason has to reach the screen
 * as a generic sentence instead of being dropped — the entry the user is asking about is the
 * one a strict union would discard.
 */
export type NotificationFailureReason =
  /** No `ezpds` block, or one this version can't parse — a relay sending junk. */
  | 'MALFORMED_PAYLOAD'
  /** The key or the pins couldn't be read: nothing registered, or the Keychain was still
   *  locked from a reboot. */
  | 'KEYS_UNAVAILABLE'
  /** No pinned key carries the payload's `kid` — the key-desync signature. */
  | 'UNKNOWN_KID'
  /** Candidates existed and none opened it. HPKE Auth mode failing closed. */
  | 'OPEN_FAILED'
  /** It opened — so it was authentic — but carried nothing renderable. */
  | 'MALFORMED_PLAINTEXT'
  // eslint-disable-next-line @typescript-eslint/ban-types
  | (string & {});

/** One failure the extension recorded. */
export type NotificationFailure = {
  /** ISO 8601, from the extension's clock. */
  at: string;
  reason: NotificationFailureReason;
  /** The payload's sender-key id, where it got far enough to have one. */
  kid: number | null;
};

/** What this device holds, for the diagnostics surface. Public halves only. */
export type NotificationDiagnostics = {
  deviceUuid: string | null;
  notificationKeyId: string | null;
  hasApnsToken: boolean;
  /** Pinned sender keys per hosting server. Keyed by host because `kid` is instance-scoped:
   *  two Custos instances both start numbering at 1. */
  pinnedHosts: Record<string, SenderKey[]>;
  /**
   * What the extension could not verify, newest first.
   *
   * iOS won't let an extension suppress an alert push, so an unverifiable payload still shows a
   * banner saying so. These are what turn that banner into something diagnosable.
   */
  recentFailures: NotificationFailure[];
};

export type NotificationsError =
  /** Run `unlockIdentity(did)` and retry. */
  | { code: 'SESSION_LOCKED'; reason: UnlockReason }
  | { code: 'RATE_LIMITED'; retryAfter: string | null }
  | { code: 'IDENTITY_NOT_FOUND'; message: string }
  | { code: 'KEY_GENERATION_FAILED'; message: string }
  | { code: 'KEYCHAIN_ERROR'; message: string }
  | { code: 'SERVER_ERROR'; status: number | null; message: string }
  | { code: 'NETWORK_ERROR'; message: string };

/**
 * Register this device for push on the identity's hosting Custos.
 *
 * Called at onboarding completion (post-promotion, so the account exists) and whenever the APNs
 * token changes. Idempotent server-side — it upserts on `(did, deviceUuid)` — so a caller never
 * has to track whether it already registered.
 *
 * Resolves rather than rejects for the two ordinary "no" answers (no token yet, host has no
 * relay), so a completion screen has nothing to catch on a simulator or a non-Custos host.
 */
export async function registerForNotifications(did: string): Promise<RegistrationOutcome> {
  return invoke<RegistrationOutcome>('register_for_notifications', { did });
}

/**
 * Re-fetch and re-pin the identity's host's sender-key set.
 *
 * Call on every successful contact with a Custos. That cadence is the design's
 * compromise-window property: until a device re-pins, a compromised sender key plus a colluding
 * relay can forge notification content for it.
 */
export async function refreshNotificationSenderKeys(did: string): Promise<SenderKeyPinning> {
  return invoke<SenderKeyPinning>('refresh_notification_sender_keys', { did });
}

/** What this device holds. Read-only, no network, no identity needed. */
export async function getNotificationDiagnostics(): Promise<NotificationDiagnostics> {
  return invoke<NotificationDiagnostics>('get_notification_diagnostics');
}

/**
 * Forget the extension's recorded failures.
 *
 * The acknowledge half of the diagnostic: once the user has re-pinned or switched relays, a log
 * that keeps reporting the old problem is noise — and noise is what stops the next real report
 * from being read. Idempotent, and never rejects.
 */
export async function clearNotificationFailures(): Promise<void> {
  return invoke<void>('clear_notification_failures');
}

// pattern: Mixed (Functional Core pin-store arithmetic; Imperative Shell commands + Keychain)

//! The device half of the end-to-end-encrypted notification relay: the keys a Custos instance
//! seals push payloads to, the registration that tells it where to send them, and the pinned
//! sender-key set the Notification Service Extension verifies against.
//!
//! - `register_for_notifications(did)` — POST `/v1/notifications/register` over a
//!   `SessionProvider::full_access_client` session: device uuid, notification `did:key`, APNs
//!   token, the app's own bundle id as the topic. Re-pins on the same contact — the calling
//!   cadence (each onboarding flow's completion + once per app open per identity,
//!   fire-and-forget in `+page.svelte`'s `syncNotifications`) is a security property: until a
//!   device re-pins, a compromised sender key plus a colluding relay can forge content for it
//! - `refresh_notification_sender_keys(did)` — GET `/v1/notifications/sender-keys`, the re-pin
//! - `get_notification_diagnostics()` — a no-network, no-identity read of what the device holds
//! - `clear_notification_failures()` — acknowledge the extension's breadcrumbs
//!
//! Nothing here decrypts anything; the extension that does is a separate bundle
//! (`ios/NotificationService/`, Swift + CryptoKit). This module's job is to leave the right
//! material in the right Keychain slots under the right protection class: five app-global
//! accounts (`NOTIFICATION_ACCOUNTS`, none ever syncs) — `notification-device-uuid`,
//! `-key-priv`, `-sender-keys`, `-apns-token`, `-failures`; the three the extension touches
//! are `AfterFirstUnlock` (it runs on a locked screen), the uuid and APNs token ordinary
//! `store_item` — see each constant. `notification-failures` runs the other way: the extension
//! appends, the app only reads. iOS will not let an extension suppress an alert push, so an
//! unverifiable payload still banners ("couldn't verify"); the breadcrumbs are what let
//! Settings distinguish a key desync (open the app; it re-pins) from a relay sending junk —
//! the same banner and opposite responses. Both the pin document and the failure log read
//! **fail-open** (corrupt reads as empty), and `reason` is a plain `String`: the extension
//! versions independently, so an unrecognized entry must reach the screen generically.
//!
//! **Device-global, not per-DID.** A push carries `{v, kid, enc, ct}` and nothing else —
//! naming a DID would hand the relay and Apple the metadata the design exists to withhold —
//! so the extension has no way to choose among per-identity keys: one keypair, one
//! `device_uuid` per install, every identity registers the same public key with its own host.
//! **The pinned set is nonetheless per hosting server:** `kid` is an autoincrement column on
//! ONE instance, so two instances both publish a `kid` of 1 for unrelated keys; the extension
//! tries every candidate under the incoming `kid`, and HPKE Auth mode fails closed on a wrong
//! one. A successful fetch **replaces that host's set wholesale** — the one choice that
//! implements add-new / retire / revoke: a revoked key vanishes at the device's next contact,
//! the short-compromise-window property. A 501 (feature off) and a 503 (instance can't read
//! its own keys) both leave the stored set untouched: neither is a revocation, and clearing on
//! a bad deploy would strip every device that checked in during it. Two ordinary "no" answers
//! are **outcomes, not errors** — `AWAITING_APNS_TOKEN` and `UNSUPPORTED` — so onboarding has
//! nothing to catch; neither command is biometric-gated (nothing is signed, no identity
//! material is exposed, and a prompt at onboarding completion would be a demand the user
//! cannot connect to anything they did). Network cores (`register_impl`,
//! `fetch_sender_keys_impl`) take an `&OAuthClient` and are tested against httpmock; the
//! Keychain half is tested against the in-memory double, down to each slot's protection class
//! and the exact bytes the Swift extension writes. Serialized types mirror `$lib/ipc` exactly.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use zeroize::Zeroizing;

use crate::identity_store::IdentityStore;
use crate::oauth_client::OAuthClient;
use crate::pds_client::PdsClient;
use crate::session_provider::{SessionError, SessionProvider, UnlockReason};

// ── Keychain accounts ────────────────────────────────────────────────────────

/// The device's stable notification identifier. App-generated and device-global: the server
/// keys registrations on `(did, device_uuid)` precisely because its own `devices` rows are
/// deleted at DID promotion, so this value must outlive every identity that uses it.
const DEVICE_UUID_ACCOUNT: &str = "notification-device-uuid";

/// The per-device P-256 notification private key (raw 32-byte scalar).
///
/// `AccessibleAfterFirstUnlock`, in the shared access group — the extension decrypts on a locked
/// screen and cannot present a biometric prompt. The relaxation is bounded: this key opens
/// notification *content* and signs nothing. It is not a rotation key, not a repo signing key,
/// and its loss costs unreadable banners, never an identity.
const NOTIFICATION_KEY_ACCOUNT: &str = "notification-key-priv";

/// The pinned sender-key sets, one per hosting server. Same protection class as the private
/// key: the extension needs both in the same moment, and a key it cannot read is a payload it
/// must render as unverified.
const PINNED_SENDER_KEYS_ACCOUNT: &str = "notification-sender-keys";

/// The APNs device token, lowercase hex. Ordinary protection — only the foreground app reads it,
/// to put it in a registration request.
const APNS_TOKEN_ACCOUNT: &str = "notification-apns-token";

/// The Notification Service Extension's breadcrumb log — the only thing that process ever
/// writes, and the only slot in this module the app does not author.
///
/// Same protection class as the key and the pins, for the same reason: the extension records a
/// failure in the moment it happens, which is on a locked screen. Mirrored in Swift by
/// `NotifyKeychain.failureLogAccount`; the two bundles can only agree by both spelling it.
const FAILURE_LOG_ACCOUNT: &str = "notification-failures";

/// Every account this module owns, so `keychain.rs`'s never-sync assertion is written against
/// the list rather than a copy of it — a new slot added here is covered without anyone
/// remembering to go and add it there too.
#[cfg(test)]
pub(crate) const NOTIFICATION_ACCOUNTS: &[&str] = &[
    DEVICE_UUID_ACCOUNT,
    NOTIFICATION_KEY_ACCOUNT,
    PINNED_SENDER_KEYS_ACCOUNT,
    APNS_TOKEN_ACCOUNT,
    FAILURE_LOG_ACCOUNT,
];

/// Version tag on the stored pin document, so a later shape change can be recognized rather
/// than mis-parsed.
const PIN_DOCUMENT_VERSION: u8 = 1;

/// Version tag on the extension's failure log.
///
/// Its own constant despite currently equalling [`PIN_DOCUMENT_VERSION`]: the two documents are
/// unrelated schemas with different authors — this module owns the pin store, the Swift
/// extension owns the failure log — so sharing a number would mean a bump made for the pin
/// store's shape silently discarded every breadcrumb the extension had recorded. That is the
/// same failure this module refuses for `reason`, and it would land on the one surface whose
/// job is to work when notifications are already broken.
const FAILURE_LOG_VERSION: u8 = 1;

// ── Errors ───────────────────────────────────────────────────────────────────

// Turning the Notification Service Extension's breadcrumbs into a sentence.
//
// iOS cannot let an extension suppress an alert push, so a payload this device cannot verify
// still produces a banner — the honest "Couldn't verify a notification from your Custos
// instance". That notice is correct and completely uninformative: a key desync and a relay
// sending junk read identically on the lock screen, and they call for opposite responses.
//
// This is where the difference gets stated. Pure over its inputs, so every branch of the
// wording is testable without a push, an extension, or a device.

import type { NotificationFailure } from '$lib/ipc';

/**
 * How far back a failure still says something about the present.
 *
 * A week: long enough that a problem which fires once a day is visibly a pattern rather than a
 * one-off, short enough that a fixed problem stops being reported without the user having to
 * acknowledge it. (They still can — see `clearNotificationFailures` — but the surface must not
 * depend on their doing so.)
 */
export const FAILURE_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;

/**
 * How loudly to say it.
 *
 * Two levels, not four. The wallet's urgency ladder (safe/warning/critical/expired) belongs to
 * identity state, where the stakes are a key and a recovery window; nothing here can cost the
 * user an identity. Borrowing that vocabulary would inflate a missed banner into something it
 * shares a visual language with.
 *
 * `attention` never means "you are in danger" — it means "this will keep happening until
 * something changes".
 */
export type NotificationHealthLevel = 'quiet' | 'info' | 'attention';

export type NotificationHealth = {
  level: NotificationHealthLevel;
  /** Failures inside the window. */
  count: number;
  /** The most recent failure's timestamp, or null when there is none. */
  latest: string | null;
  /** One line naming what happened. Never a colour, never an icon alone. */
  headline: string;
  /** What it means, in the user's terms. */
  detail: string;
  /** What to do, or null when there is genuinely nothing to do. */
  advice: string | null;
};

const QUIET: NotificationHealth = {
  level: 'quiet',
  count: 0,
  latest: null,
  headline: 'No notification problems',
  detail: 'Every recent notification from your server arrived and could be verified.',
  advice: null,
};

/**
 * The per-reason wording.
 *
 * Each entry answers the same two questions — what happened, and is it on the user to act —
 * because those are what the lock-screen notice cannot say. Note that `KEYS_UNAVAILABLE` is
 * deliberately `info` and carries no advice: it is the push that arrived before the first
 * unlock after a restart, it is already fixed by the time anyone reads this, and telling
 * someone to act on it would spend their attention on nothing.
 */
const REASONS: Record<string, { level: NotificationHealthLevel; detail: string; advice: string | null }> = {
  UNKNOWN_KID: {
    level: 'attention',
    detail:
      'Your server signed these with a key this device has not seen. That usually means its notification keys changed after the last time this device checked in.',
    advice: 'Open one of your identities. Obsign refreshes the keys on every contact with your server.',
  },
  OPEN_FAILED: {
    level: 'attention',
    detail:
      'These arrived signed by a key this device knows, but did not unlock with it — so they were not really from your server, or the copy of its key here is out of date.',
    advice: 'Open one of your identities to refresh the keys. If it keeps happening, your relay may be sending notifications your server did not.',
  },
  MALFORMED_PAYLOAD: {
    level: 'attention',
    detail:
      'These were not notifications your server sent. Whatever delivers your notifications can always send something — it just cannot make it look genuine, which is why they showed as unverified.',
    advice: 'Nothing is at risk. If it keeps happening, consider pointing your server at a different notification relay.',
  },
  MALFORMED_PLAINTEXT: {
    level: 'attention',
    detail:
      'These genuinely came from your server, but this version of Obsign could not read what was inside them.',
    advice: 'Updating Obsign should fix this.',
  },
  KEYS_UNAVAILABLE: {
    level: 'info',
    detail:
      'These arrived before this iPhone had been unlocked since it last restarted, so the keys needed to read them were not available yet.',
    advice: null,
  },
};

function headlineFor(count: number): string {
  return count === 1
    ? '1 notification could not be verified'
    : `${count} notifications could not be verified`;
}

/**
 * Fold the extension's log into what Settings shows.
 *
 * The **worst** level in the window wins, and the wording comes from the reason that occurs
 * most among the failures at that level — so a week containing one genuinely benign
 * post-restart failure alongside four key-desync ones reports the desync, and a week of only
 * post-restart failures does not manufacture an alarm.
 *
 * An unrecognized reason (a newer extension than this app) counts toward the total and is
 * described generically rather than dropped: the entry the user is asking about is exactly the
 * one a stricter reader would have discarded.
 */
export function summarizeNotificationFailures(
  failures: NotificationFailure[],
  now: number = Date.now()
): NotificationHealth {
  const recent = failures.filter((failure) => {
    const at = Date.parse(failure.at);
    // An unparseable timestamp is kept, not dropped. It is still a failure that happened, and
    // silently discarding it would make a clock problem look like a clean bill of health.
    return Number.isNaN(at) || now - at <= FAILURE_WINDOW_MS;
  });
  if (recent.length === 0) return QUIET;

  const level: NotificationHealthLevel = recent.some(
    (failure) => (REASONS[failure.reason]?.level ?? 'attention') === 'attention'
  )
    ? 'attention'
    : 'info';

  const atLevel = recent.filter(
    (failure) => (REASONS[failure.reason]?.level ?? 'attention') === level
  );
  const counts = new Map<string, number>();
  for (const failure of atLevel) {
    counts.set(failure.reason, (counts.get(failure.reason) ?? 0) + 1);
  }
  const dominant = [...counts.entries()].sort((a, b) => b[1] - a[1])[0][0];
  const wording = REASONS[dominant] ?? {
    level: 'attention' as const,
    detail:
      'These could not be verified, for a reason this version of Obsign does not recognise.',
    advice: 'Updating Obsign may explain them.',
  };

  return {
    level,
    count: recent.length,
    latest: recent[0]?.at ?? null,
    headline: headlineFor(recent.length),
    detail: wording.detail,
    advice: wording.advice,
  };
}

// The extension's half of the shared Keychain contract the wallet's notification registration
// established.
//
// Every constant here is a copy of one in `apps/identity-wallet/src-tauri/src/keychain.rs`
// and `notifications.rs`, because the two processes are separate bundles that can only agree
// by both spelling the same strings. Nothing else may be added: the app writes, the
// extension reads, and the single exception (the breadcrumb log) is written by both.
//
// # Why no `kSecAttrAccessGroup` anywhere below
//
// Exactly the wallet's stance, and for the same reason. Naming a group means discovering the
// team's `AppIdentifierPrefix` at runtime, which adds a failure mode to the one code path
// that must work on a locked screen. Instead the entitlement's *shape* carries the contract:
// `$(AppIdentifierPrefix)org.obsign.shared` is listed FIRST in both bundles' entitlements, so
// an unqualified write lands there and an unqualified read searches every entitled group.
// `just bundle-identity-check` and `just ios-template-check` enforce the ordering.

import Foundation
import Security

enum NotifyKeychain {
    /// `keychain::SERVICE`. Changing it orphans every item the app ever wrote.
    static let service = "ezpds-identity-wallet"

    /// `notifications::NOTIFICATION_KEY_ACCOUNT` — the raw 32-byte P-256 scalar.
    static let notificationKeyAccount = "notification-key-priv"
    /// `notifications::PINNED_SENDER_KEYS_ACCOUNT` — the per-host pin document.
    static let pinnedSenderKeysAccount = "notification-sender-keys"
    /// `notifications::FAILURE_LOG_ACCOUNT` — the breadcrumbs Settings surfaces.
    static let failureLogAccount = "notification-failures"

    /// Read a device-local generic password.
    ///
    /// Returns `nil` for a missing item *and* for a locked Keychain (`errSecInteractionNotAllowed`,
    /// what a push arriving before the first unlock after a reboot sees). The caller renders both
    /// as the unverified notice, so the distinction would buy nothing here — it is drawn in the
    /// breadcrumb instead, where it is the difference between "reboot, this will fix itself" and
    /// "your keys and your server's disagree".
    static func read(account: String) -> Data? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne,
        ]
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess else { return nil }
        return item as? Data
    }

    /// Write a device-local generic password under `kSecAttrAccessibleAfterFirstUnlock`.
    ///
    /// Delete-then-add, matching `keychain::store_item_after_first_unlock` exactly:
    /// `SecItemUpdate` cannot change an existing item's protection class, so an update would
    /// silently inherit whatever class the first writer set — and on this account the class is
    /// the whole contract, since a breadcrumb about a locked-screen failure is itself written
    /// on a locked screen.
    @discardableResult
    static func write(account: String, data: Data) -> Bool {
        let identity: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
        SecItemDelete(identity as CFDictionary)

        var attributes = identity
        attributes[kSecValueData as String] = data
        attributes[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlock
        return SecItemAdd(attributes as CFDictionary, nil) == errSecSuccess
    }
}

/// One published sender key, mirroring `notifications::SenderKey`.
struct PinnedSenderKey: Decodable, Equatable {
    let kid: Int
    let publicKey: String
}

/// The pin document, mirroring `notifications::PinnedSenderKeys`.
struct PinnedSenderKeys: Decodable {
    static let supportedVersion = 1

    let version: Int
    /// Hosting server → that server's published set.
    let hosts: [String: [PinnedSenderKey]]

    /// Every key published under `kid`, across every host this device has pinned against.
    ///
    /// A flat list on purpose. `kid` is an autoincrement column on *one* instance, so a wallet
    /// holding identities on two servers will hold two unrelated keys under `kid: 1` — and the
    /// push that arrives carries no DID, no handle, and no host, because naming one would give
    /// the relay and Apple exactly the metadata this design exists to withhold. So the
    /// extension cannot know which host sent it, and tries all of them. That costs nothing and
    /// risks nothing: HPKE Auth mode either authenticates against a given sender key or it
    /// does not, so a wrong candidate fails closed and the next is tried.
    func candidates(for kid: Int) -> [String] {
        hosts.values.flatMap { $0 }.filter { $0.kid == kid }.map(\.publicKey)
    }

    /// Parse the stored document, treating an unreadable or foreign-version one as empty.
    ///
    /// **Fail-open**, exactly as `notifications::load_pins` is, and for the same reason: this
    /// holds public keys the server hands back on the next contact. Refusing to read it would
    /// forfeit nothing an attacker wants and cost the user the notification in front of them.
    /// The safety property lives in HPKE, not here — an empty candidate set renders the
    /// unverified notice, which is the correct outcome.
    static func parse(_ raw: Data?) -> PinnedSenderKeys {
        guard let raw,
              let decoded = try? JSONDecoder().decode(PinnedSenderKeys.self, from: raw),
              decoded.version == supportedVersion
        else { return PinnedSenderKeys(version: supportedVersion, hosts: [:]) }
        return decoded
    }
}

// The failure ladder, with no crypto and no Keychain.
//
// Every branch here ends in a banner the user reads, so each one is worth pinning: the
// extension's single rule is that authenticated content renders as content and everything
// else renders as the unverified notice, and these are the cases where that rule could quietly
// erode into "render whatever we managed to parse".

import XCTest

private func envelope(v: Int = 1, kid: Int = 1, enc: String = "AQID", ct: String = "BAUG") -> [AnyHashable: Any] {
    ["aps": ["alert": ["title": "Custos", "body": "Encrypted notification"]],
     "ezpds": ["v": v, "kid": kid, "enc": enc, "ct": ct]]
}

final class NotifyEnvelopeTests: XCTestCase {
    func testAWellFormedEnvelopeParses() throws {
        let parsed = try XCTUnwrap(NotifyEnvelope.parse(userInfo: envelope()))
        XCTAssertEqual(parsed.kid, 1)
        XCTAssertEqual(parsed.enc, Data([0x01, 0x02, 0x03]))
        XCTAssertEqual(parsed.ct, Data([0x04, 0x05, 0x06]))
    }

    /// A push with no `ezpds` block at all — what a relay sending junk, or a future
    /// content-free ping, looks like.
    func testAPushWithoutTheEnvelopeIsRejected() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: ["aps": ["alert": "hello"]]))
    }

    /// A newer instance sealing for a newer extension. Guessing at it would be the one way
    /// unverifiable bytes could reach the screen as content.
    func testAFutureVersionIsRejectedRatherThanGuessed() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(v: 2)))
    }

    func testEmptyOrUndecodableFieldsAreRejected() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(enc: "")))
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(ct: "!!!not base64!!!")))
        // 4n+1 is a length no base64 encoding can produce; re-padding it would manufacture a
        // decodable string out of corrupt input.
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(enc: "AAAAA")))
    }

    func testBase64UrlDecodesTheAlphabetTheRustSideEmits() {
        // URL_SAFE_NO_PAD: '-' and '_' for '+' and '/', and no '=' padding.
        XCTAssertEqual(Data(base64URLEncoded: "-_8"), Data([0xfb, 0xff]))
        XCTAssertEqual(Data(base64URLEncoded: "AQ"), Data([0x01]))
    }
}

final class DidKeyTests: XCTestCase {
    /// A real P-256 did:key. The pinned sender keys arrive in exactly this form, so a
    /// regression here silently empties every candidate set and turns every push into the
    /// unverified notice.
    private let sample = "did:key:REDACTED"

    func testAP256DidKeyDecodesToACompressedPoint() throws {
        let bytes = try XCTUnwrap(DidKey.p256PublicKeyBytes(from: sample))
        XCTAssertEqual(bytes.count, DidKey.compressedPointLength)
        XCTAssertTrue(bytes[0] == 0x02 || bytes[0] == 0x03, "compressed SEC1 parity tag")
    }

    func testNonP256AndMalformedKeysAreRejected() {
        // An Ed25519 did:key — right shape, wrong multicodec.
        XCTAssertNil(DidKey.p256PublicKeyBytes(
            from: "did:key:REDACTED"
        ))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: "did:key:zNOTBASE58!!!"))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: "did:plc:abc123"))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: ""))
    }

    func testBase58PreservesLeadingZeroBytes() {
        // '1' is base58's zero digit; the long division carries no magnitude for it, so the
        // leading zeros have to be restored explicitly or every multicodec prefix shifts.
        XCTAssertEqual(Base58.decode("11"), [0x00, 0x00])
        XCTAssertEqual(Base58.decode("12"), [0x00, 0x01])
    }
}

final class NotifyResolverTests: XCTestCase {
    private let key = Data(repeating: 0x01, count: 32)

    private func pins(_ entries: [(Int, String)]) -> PinnedSenderKeys {
        PinnedSenderKeys(
            version: 1,
            hosts: ["https://pds.example.com": entries.map { PinnedSenderKey(kid: $0.0, publicKey: $0.1) }]
        )
    }

    func testAJunkPushIsUnverifiedRatherThanRendered() {
        let outcome = NotifyResolver.resolve(
            userInfo: ["aps": ["alert": "Buy crypto now"]],
            recipientPrivateKey: key,
            pins: pins([])
        )
        XCTAssertEqual(outcome, .unverified(.malformedPayload, kid: nil))
    }

    /// The post-reboot locked Keychain, and the never-registered device, reach the same
    /// place — the extension cannot tell them apart and must not pretend to.
    func testAnUnreadableKeyIsUnverified() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 3),
            recipientPrivateKey: nil,
            pins: pins([(3, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.keysUnavailable, kid: 3))
    }

    /// The key-desync signature: the instance rotated and this device has not re-pinned. It
    /// is recorded distinctly because it is the one failure Settings can give real advice
    /// about — open the app so it re-pins.
    func testAnUnpinnedKidIsRecordedAsItsOwnFailure() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 9),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.unknownKid, kid: 9))
    }

    /// Candidates existed and none opened it. Reached here with junk ciphertext, which is
    /// precisely the replayed-junk payload the acceptance criteria name.
    func testCandidatesThatAllFailToOpenAreUnverified() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 1),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.openFailed, kid: 1))
    }

    /// An undecodable `did:key` is skipped, not fatal — but with nothing left to try the
    /// verdict is still "did not open", never a render.
    func testAnUndecodableCandidateIsSkipped() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 1),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:zGARBAGE"), (1, "did:key:zAlsoGarbage")])
        )
        XCTAssertEqual(outcome, .unverified(.openFailed, kid: 1))
    }

    func testTheUnverifiedNoticeNeverImpersonatesContent() {
        XCTAssertTrue(NotifyResolver.unverifiedBody.contains("Couldn't verify"))
        XCTAssertNotEqual(NotifyResolver.unverifiedTitle, "Custos")
    }
}

final class NotifyPayloadRouteTests: XCTestCase {
    private func decode(_ json: String) -> NotifyPayload? {
        NotifyPayload.decode(Data(json.utf8))
    }

    /// The `login-approval` payload the consent push seals: the routing identifiers decode
    /// and become the delivered notification's route block, alongside the payload `type`.
    func testALoginApprovalPayloadYieldsARouteBlock() throws {
        let payload = try XCTUnwrap(decode(
            #"{"type":"login-approval","title":"Sign-in request","body":"b","data":{"requestId":"poauth_x","did":"did:plc:abc","clientName":"App","origin":"https://a"},"pad":"  "}"#
        ))
        let route = try XCTUnwrap(NotifyRoute.userInfo(for: payload))
        XCTAssertEqual(route, ["type": "login-approval", "requestId": "poauth_x", "did": "did:plc:abc"])
        // Allowlist, not passthrough: clientName/origin render in the banner but never route.
        XCTAssertNil(route["clientName"])
        XCTAssertNil(route["origin"])
    }

    /// A payload without routing data — every pre-Phase-C payload — still renders, and
    /// contributes no route block at all.
    func testAPayloadWithoutDataRendersWithNoRoute() throws {
        let payload = try XCTUnwrap(decode(
            #"{"type":"ops_alert","title":"t","body":"b","pad":""}"#
        ))
        XCTAssertNil(payload.data)
        XCTAssertNil(NotifyRoute.userInfo(for: payload))
    }

    /// A `data` block this build doesn't understand degrades to "no route", never to a
    /// decode failure that would turn an authenticated banner into the unverified notice.
    func testUnrecognizedOrMalformedDataNeverFailsThePayload() throws {
        let unknownFields = try XCTUnwrap(decode(
            #"{"type":"x","title":"t","body":"b","data":{"claimAttemptId":"clm_1"},"pad":""}"#
        ))
        XCTAssertNil(NotifyRoute.userInfo(for: unknownFields))

        let wrongTypes = try XCTUnwrap(decode(
            #"{"type":"x","title":"t","body":"b","data":{"requestId":7,"did":["a"]},"pad":""}"#
        ))
        XCTAssertNil(NotifyRoute.userInfo(for: wrongTypes))

        let notAnObject = try XCTUnwrap(decode(
            #"{"type":"x","title":"t","body":"b","data":"nope","pad":""}"#
        ))
        XCTAssertNil(NotifyRoute.userInfo(for: notAnObject))
    }
}

final class NotifyBreadcrumbTests: XCTestCase {
    func testTheLogIsNewestFirstAndBounded() {
        var log = NotifyFailureLog.empty
        for index in 0..<(NotifyFailureLog.capacity + 5) {
            log = log.appending(NotifyFailure(at: "t\(index)", reason: "OPEN_FAILED", kid: index))
        }
        XCTAssertEqual(log.failures.count, NotifyFailureLog.capacity)
        XCTAssertEqual(log.failures.first?.kid, NotifyFailureLog.capacity + 4, "newest first")
        XCTAssertEqual(log.failures.last?.kid, 5, "the oldest entries are the ones dropped")
    }

    /// Fail-open, like the pin store: a damaged log must not cost the user the breadcrumb
    /// being recorded right now.
    func testACorruptOrForeignVersionLogReadsAsEmpty() {
        XCTAssertTrue(NotifyFailureLog.parse(Data("{not json".utf8)).failures.isEmpty)
        XCTAssertTrue(NotifyFailureLog.parse(nil).failures.isEmpty)
        let foreign = Data(#"{"version":99,"failures":[{"at":"t","reason":"OPEN_FAILED","kid":1}]}"#.utf8)
        XCTAssertTrue(NotifyFailureLog.parse(foreign).failures.isEmpty)
    }
}

final class PinnedSenderKeysTests: XCTestCase {
    /// Two instances both start their `kid` sequence at 1, and the push names no host — so
    /// every key under the incoming `kid` is a candidate, across every pinned host.
    func testCandidatesSpanEveryHost() {
        let pins = PinnedSenderKeys(version: 1, hosts: [
            "https://a.example.com": [PinnedSenderKey(kid: 1, publicKey: "did:key:zA")],
            "https://b.example.com": [PinnedSenderKey(kid: 1, publicKey: "did:key:zB"),
                                      PinnedSenderKey(kid: 2, publicKey: "did:key:zC")],
        ])
        XCTAssertEqual(Set(pins.candidates(for: 1)), ["did:key:zA", "did:key:zB"])
        XCTAssertEqual(pins.candidates(for: 2), ["did:key:zC"])
        XCTAssertTrue(pins.candidates(for: 3).isEmpty)
    }

    func testACorruptPinDocumentReadsAsEmpty() {
        XCTAssertTrue(PinnedSenderKeys.parse(Data("{nope".utf8)).hosts.isEmpty)
        XCTAssertTrue(PinnedSenderKeys.parse(nil).hosts.isEmpty)
    }
}

// The pure half of the Notification Service Extension: everything that turns bytes into
// other bytes, with no Keychain, no CryptoKit, and no UserNotifications.
//
// It lives apart from NotificationService.swift for the same reason the wallet's Rust keeps
// `_impl` cores away from Tauri commands — this is the part an XCTest can drive on a
// simulator, and the part the Rust↔CryptoKit fixture cross-check exercises.

import Foundation

/// The `ezpds` object a sealed push carries beside its placeholder `aps` alert.
///
/// Wire shape (see `crates/notify-relay/src/protocol.rs`):
/// `{ "v": 1, "kid": 3, "enc": "<b64url>", "ct": "<b64url>" }`
struct NotifyEnvelope: Equatable {
    /// Protocol version. Only `1` is understood; anything else is a payload sealed by a
    /// newer instance for a newer extension, and must render as unverified rather than be
    /// guessed at.
    static let supportedVersion = 1

    /// The `userInfo` key the sealed block travels under. Named once because it is used for two
    /// opposite purposes — reading the envelope, and *removing* it before delivery — and a typo
    /// in the second would leak ciphertext into the delivered-notification list silently.
    static let userInfoKey = "ezpds"

    let version: Int
    /// The instance-scoped sender-key id. Not a global identifier: two Custos instances both
    /// start their `kid` sequence at 1, which is why the pin store is keyed by host and every
    /// candidate under this id is tried.
    let kid: Int
    /// HPKE encapsulated key — 65 raw bytes for DHKEM(P-256).
    let enc: Data
    /// AEAD ciphertext with the 16-byte AES-GCM tag appended.
    let ct: Data

    /// Read the envelope out of an APNs `userInfo` dictionary.
    ///
    /// Returns `nil` for anything that is not a well-formed v1 envelope — a junk push from a
    /// misbehaving relay, a `content-available` ping, or a future version. The caller renders
    /// all of those identically (the unverified notice), so this deliberately does not
    /// distinguish "absent" from "malformed": neither is content this device can vouch for.
    static func parse(userInfo: [AnyHashable: Any]) -> NotifyEnvelope? {
        guard let block = userInfo[userInfoKey] as? [String: Any],
              let version = block["v"] as? Int,
              version == supportedVersion,
              let kid = block["kid"] as? Int,
              let encText = block["enc"] as? String,
              let ctText = block["ct"] as? String,
              let enc = Data(base64URLEncoded: encText),
              let ct = Data(base64URLEncoded: ctText),
              !enc.isEmpty, !ct.isEmpty
        else { return nil }

        return NotifyEnvelope(version: version, kid: kid, enc: enc, ct: ct)
    }
}

/// The decrypted plaintext a Custos instance seals.
///
/// Wire shape: `{ "type": …, "title": …, "body": …, "data": { … }, "pad": "…" }`. `pad` is
/// dropped on the floor here — its whole job was to make the *serialized APNs request* land
/// on a padding bucket, which is finished by the time these bytes exist. `data` is decoded
/// only for the small allowlist of routing fields below; everything else in it is ignored.
struct NotifyPayload: Equatable, Decodable {
    let type: String
    let title: String
    let body: String
    /// Structured routing data the sealing instance attached (a request id, a subject DID).
    /// Optional and tolerant: a payload without it — or with fields this build doesn't know —
    /// still renders; only the recognized identifiers survive into the delivered notification.
    let data: NotifyRouteData?

    private enum CodingKeys: String, CodingKey {
        case type, title, body, data
    }

    /// Decode sealed plaintext, rejecting a payload with nothing to render.
    ///
    /// An empty title *and* body would produce a banner indistinguishable from a silent
    /// delivery failure, so it is treated as a malformed payload and rendered as the
    /// unverified notice instead — the extension's one rule is that it never shows something
    /// it cannot stand behind. A `data` block that fails to decode as the routing shape is
    /// dropped (the banner still renders); it never fails the whole payload.
    static func decode(_ plaintext: Data) -> NotifyPayload? {
        guard let payload = try? JSONDecoder().decode(NotifyPayload.self, from: plaintext),
              !(payload.title.isEmpty && payload.body.isEmpty)
        else { return nil }
        return payload
    }
}

/// The routing identifiers a verified payload may carry in `data`.
///
/// A deliberate allowlist rather than a passthrough: only these fields ever reach the
/// delivered notification's `userInfo`, so the app can never be steered by a field the
/// extension didn't decide to forward.
struct NotifyRouteData: Equatable, Decodable {
    /// A pending OAuth consent request id (`login-approval`).
    let requestId: String?
    /// The account DID the notification concerns, so a multi-identity wallet opens the
    /// right one.
    let did: String?

    private enum CodingKeys: String, CodingKey {
        case requestId, did
    }

    init(requestId: String?, did: String?) {
        self.requestId = requestId
        self.did = did
    }

    init(from decoder: Decoder) throws {
        // Tolerant field-by-field decode: a `data` block whose recognized fields have
        // unexpected types reads as absent fields, never a decode failure that would take
        // the whole (already authenticated) payload down with it.
        let container = try? decoder.container(keyedBy: CodingKeys.self)
        requestId = container.flatMap { try? $0.decodeIfPresent(String.self, forKey: .requestId) } ?? nil
        did = container.flatMap { try? $0.decodeIfPresent(String.self, forKey: .did) } ?? nil
    }
}

/// The routing block a verified payload leaves in the delivered notification.
enum NotifyRoute {
    /// The `userInfo` key the app reads on a notification tap. Distinct from
    /// `NotifyEnvelope.userInfoKey` (`ezpds`, the sealed block, which is always stripped):
    /// this one is *written* by the extension, and only ever after HPKE Auth verified the
    /// payload — so its presence is itself the "this came from your instance" statement.
    static let userInfoKey = "ezpdsRoute"

    /// What a rendered payload contributes to the delivered notification's `userInfo`, or
    /// `nil` when it carries nothing to route on. Pure so the tests can pin the contract:
    /// only allowlisted identifiers, plus the payload `type` the app dispatches on.
    static func userInfo(for payload: NotifyPayload) -> [String: String]? {
        var route: [String: String] = [:]
        if let requestId = payload.data?.requestId { route["requestId"] = requestId }
        if let did = payload.data?.did { route["did"] = did }
        guard !route.isEmpty else { return nil }
        route["type"] = payload.type
        return route
    }
}

// MARK: - base64url

extension Data {
    /// Decode unpadded base64url — the encoding every binary field in the envelope uses
    /// (`URL_SAFE_NO_PAD` on the Rust side). Foundation only speaks standard base64 with
    /// padding, so translate the alphabet and re-pad.
    init?(base64URLEncoded input: String) {
        var text = input.replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        let remainder = text.count % 4
        if remainder == 1 {
            // 4n+1 is not a length any base64 encoding can produce; padding it would
            // manufacture a decodable string out of corrupt input.
            return nil
        }
        if remainder > 0 {
            text += String(repeating: "=", count: 4 - remainder)
        }
        guard let decoded = Data(base64Encoded: text) else { return nil }
        self = decoded
    }
}

// MARK: - did:key

/// Decode a P-256 `did:key` into its raw SEC1 public-key bytes.
///
/// The pinned sender keys arrive from Custos as `did:key:z…` strings and are stored verbatim
/// by the wallet (`notifications.rs`), so the extension has to undo the encoding itself:
/// multibase base58btc (`z` prefix) wrapping the multicodec varint `0x1200` — written
/// little-endian-base128 as `0x80 0x24` — followed by a 33-byte compressed point.
///
/// Returns `nil` for anything that is not exactly that. A sender key this device cannot
/// decode is simply not a candidate; HPKE Auth mode would fail closed on it anyway, so
/// skipping costs nothing and misreading could not gain anything.
enum DidKey {
    /// The multicodec prefix for `p256-pub`, varint-encoded.
    static let p256Prefix: [UInt8] = [0x80, 0x24]
    /// A compressed SEC1 P-256 point: 1 tag byte + 32-byte X.
    static let compressedPointLength = 33

    static func p256PublicKeyBytes(from didKey: String) -> Data? {
        guard didKey.hasPrefix("did:key:z") else { return nil }
        let multibase = String(didKey.dropFirst("did:key:z".count))
        guard let decoded = Base58.decode(multibase),
              decoded.count == p256Prefix.count + compressedPointLength,
              Array(decoded.prefix(p256Prefix.count)) == p256Prefix
        else { return nil }
        return Data(decoded.dropFirst(p256Prefix.count))
    }
}

/// base58btc, the one multibase alphabet `did:key` uses.
///
/// Hand-rolled because the extension links nothing but system frameworks: a Swift package
/// dependency in an NSE is a second supply chain in the one target that runs on a locked
/// screen, for ~30 lines of long division.
enum Base58 {
    private static let alphabet = Array("REDACTED".utf8)

    static func decode(_ input: String) -> [UInt8]? {
        var bytes: [UInt8] = [0]
        for character in input.utf8 {
            guard let value = alphabet.firstIndex(of: character) else { return nil }
            var carry = value
            for index in bytes.indices.reversed() {
                carry += 58 * Int(bytes[index])
                bytes[index] = UInt8(carry & 0xff)
                carry >>= 8
            }
            while carry > 0 {
                bytes.insert(UInt8(carry & 0xff), at: 0)
                carry >>= 8
            }
        }
        // Every leading '1' encodes one leading zero byte, which the arithmetic above cannot
        // recover (it carries no magnitude).
        var leadingZeros = 0
        for character in input.utf8 {
            guard character == alphabet[0] else { break }
            leadingZeros += 1
        }
        // Drop the seed byte and any zeros the long division introduced, then restore the
        // encoded ones.
        let significant = Array(bytes.drop(while: { $0 == 0 }))
        return Array(repeating: 0, count: leadingZeros) + significant
    }
}

